import sys
from pathlib import Path
from openpyxl import load_workbook

wb = load_workbook(Path(sys.argv[1]) / "SPEC_checklist.xlsx")
ws = wb["Requirements"]
for dv in ws.data_validations.dataValidation:
    print(dv.sqref, dv.formula1)
print(ws.max_row, ws.auto_filter.ref)
for r in range(2, ws.max_row + 1):
    if ws.cell(row=r, column=1).value in ("R17", "R20", "R147", "R150"):
        print([ws.cell(row=r, column=c).value for c in range(1, 10)])
print([ws.cell(row=ws.max_row, column=c).value for c in range(1, 10)])
for row in wb["Summary"].iter_rows():
    for cell in row:
        if isinstance(cell.value, str) and cell.value.startswith("=") and cell.row < 8:
            print(cell.coordinate, cell.value)

