"""Probe: how does a cached page describe itself? Cache only."""
import json
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
for f in (root / "cache" / "pages").glob("*"):
    try:
        e = json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        continue
    key = e.get("key") or ""
    if any(n in key for n in sys.argv[2:]) and "robots.txt" not in key:
        body = (e.get("value") or {}).get("body") or ""
        print("=" * 70, "\n", key)
        for m in re.finditer(r'(?is)<meta[^>]+(?:description|generator|author)[^>]*>', body):
            print("META", m.group(0)[:300].encode("ascii", "replace").decode())
        text = re.sub(r"(?s)<[^>]+>", " ", re.sub(r"(?is)<(script|style)\b.*?</\1>", " ", body))
        for m in re.finditer(r"(?i)[^.]{0,140}\b(AI[- ]generated|generated|automat\w+|sources?|compiled|research agent|disclaimer|sec filings?|proxy)\b[^.]{0,140}", text):
            print("..", re.sub(r"\s+", " ", m.group(0)).strip()[:300].encode("ascii", "replace").decode())

