  }
  "requirements: $($last - 1); unique ids: $($ids.Count); blank required cells: $blank"
  $tally.GetEnumerator() | Sort-Object Name | ForEach-Object { "  {0}: {1}" -f $_.Name, $_.Value }
  "filter range: " + $req.AutoFilter.Range.Address()
  "last modified by: [" + $wb.BuiltinDocumentProperties.Item("Last Author").Value + "] author: [" + $wb.BuiltinDocumentProperties.Item("Author").Value + "]"
  $wb.Close($false)
} finally { $xl.Quit(); [void][Runtime.InteropServices.Marshal]::ReleaseComObject($xl) }

