"""Print the passages of cached primary sources that list leaders, for drafting the gold sets by hand."""
import json
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
sys.path.insert(0, str(root))
from leadership.sources.web import clean_text  # noqa: E402

pages = {}
for f in (root / "cache" / "pages").glob("*"):
    try:
        e = json.loads(f.read_text(encoding="utf-8"))
        pages[e["key"]] = (e["value"] or {}).get("body") or ""
    except Exception:
        pass


def show(part, patterns, width=700, limit=6):
    for key, body in pages.items():
        if key.endswith(part):
            text = clean_text(body)
            print("=" * 80, "\n", key, len(text), "chars")
            n = 0
            for pat in patterns:
                for m in re.finditer(pat, text):
                    print(f"--- [{pat}] @{m.start()}")
                    print(re.sub(r"[ \t]+", " ", text[max(0, m.start() - 100):m.start() + width]).encode("ascii", "replace").decode())
                    n += 1
                    if n >= limit:
                        return


mode = sys.argv[2]
if mode == "robinhood":
    show("hood-20260422.htm", [r"Information about our executive officers", r"Executive Officers\n", r"has been our Chief"], 1800, 4)
    show("hood-20260507.htm", [r"Item 5\.02"], 1500, 1)
    show("robinhood.com/us/en/about-us/", [r"^"], 1200, 1)
else:
    show("campfire.ai/basecamp", [r"^"], 6000, 1)
    show("campfire.ai/blog", [r"Head of|VP |Vice President|Chief|CEO|Founder"], 260, 14)

