import json
import re
import sys
from pathlib import Path

root = Path(sys.argv[1])
for f in (root / "cache" / "pages").glob("*"):
    try:
        e = json.loads(f.read_text(encoding="utf-8"))
    except Exception:
        continue
    key = e.get("key") or ""
